const ELEMENT_PROP_KEYS = new Set(["theme","label","price","note","hold","accent","fontFamily","ink","background","scale","delay","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  label: "Pricing",
  price: "Free.",
  note: "That’s the whole pricing page.",
  hold: 40,
  fontFamily: "Albert Sans",
  scale: 1,
  delay: 0,
  speed: 1,
};

type PricePageElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof PricePageBase>;

const PricePageInner = forwardRef<
  HTMLDivElement,
  PricePageElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<PricePage>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <PricePageBase
          {...(componentProps as unknown as ComponentProps<typeof PricePageBase>)}
        />
      </div>
    </Sequence>
  );
});

export const PricePage = Interactive.withSchema({
  Component: PricePageInner,
  componentName: "<PricePage>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
